import { Camera } from '@capacitor/camera';
import { Filesystem, Directory } from '@capacitor/filesystem';
import { Preferences } from '@capacitor/preferences';

export async function capturePhoto(): Promise<string> {
  const result = await Camera.takePhoto({
    saveToGallery: false,
    includeMetadata: true,
  });

  if (!result.thumbnail) {
    throw new Error('No photo data found in thumbnail');
  }

  const isoTimestamp = new Date().toISOString();
  const path = `photos/${isoTimestamp}.jpeg`;

  await Filesystem.writeFile({
    path: path,
    data: result.thumbnail,
    directory: Directory.Data,
    recursive: true,
  });

  const photos = await listPhotos();
  photos.push(path);

  await Preferences.set({
    key: 'photo_index',
    value: JSON.stringify(photos),
  });

  return path;
}

export async function listPhotos(): Promise<string[]> {
  const { value } = await Preferences.get({ key: 'photo_index' });
  if (value === null) {
    return [];
  }
  try {
    return JSON.parse(value);
  } catch (e) {
    return [];
  }
}

export async function deletePhoto(path: string): Promise<void> {
  try {
    await Filesystem.deleteFile({
      path: path,
      directory: Directory.Data,
    });
  } catch (error) {
    console.warn(`Filesystem.deleteFile failed for path: ${path}`, error);
  }

  const photos = await listPhotos();
  const updatedPhotos = photos.filter((p) => p !== path);

  await Preferences.set({
    key: 'photo_index',
    value: JSON.stringify(updatedPhotos),
  });
}

import * as gallery from './gallery';
import { Filesystem, Directory } from '@capacitor/filesystem';

// Expose on window.gallery
(window as any).gallery = gallery;

async function renderGallery() {
  const listContainer = document.getElementById('gallery-list');
  if (!listContainer) return;
  listContainer.innerHTML = '';
  try {
    const photos = await gallery.listPhotos();
    for (const photoPath of photos) {
      const item = document.createElement('div');
      item.style.display = 'inline-block';
      item.style.margin = '10px';
      item.style.textAlign = 'center';

      const img = document.createElement('img');
      try {
        const fileData = await Filesystem.readFile({
          path: photoPath,
          directory: Directory.Data,
        });
        img.src = `data:image/jpeg;base64,${fileData.data}`;
      } catch (e) {
        console.error('Failed to read image file', e);
      }
      img.style.width = '150px';
      img.style.height = '150px';
      img.style.objectFit = 'cover';
      img.style.display = 'block';
      img.style.borderRadius = '8px';
      img.style.border = '1px solid #ccc';

      const delBtn = document.createElement('button');
      delBtn.textContent = 'Delete';
      delBtn.style.marginTop = '5px';
      delBtn.addEventListener('click', async () => {
        await gallery.deletePhoto(photoPath);
        renderGallery();
      });

      item.appendChild(img);
      item.appendChild(delBtn);
      listContainer.appendChild(item);
    }
  } catch (err) {
    console.error('Error rendering gallery', err);
  }
}

function init() {
  const captureBtn = document.getElementById('capture-btn');
  const captureStatus = document.getElementById('capture-status');

  if (captureStatus) {
    captureStatus.textContent = 'idle';
  }

  if (captureBtn) {
    captureBtn.addEventListener('click', async () => {
      if (captureStatus) {
        captureStatus.textContent = 'capturing';
      }
      try {
        await gallery.capturePhoto();
        if (captureStatus) {
          captureStatus.textContent = 'saved';
        }
        renderGallery();
      } catch (error: any) {
        if (captureStatus) {
          captureStatus.textContent = `error: ${error.message || error}`;
        }
      }
    });
  }

  renderGallery();
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}
